occlusion={1:[2,4,5,6],2:[4],3:[4],4:[12,14],5:[14],6:[7],7:[14,16],
 8:[9],9:[13,25,26],10:[13],11:[12,13],12:[14],13:[14],14:[27,36],
 15:[14],16:[14,23,28],17:[19,20],18:[19],19:[21,22,23,24,44],
 20:[22,23],21:[24,44,45],22:[23,24],23:[42,43,44],24:[23,44],
 25:[26,29],26:[36],27:[36],28:[36,41,43],29:[26,31,33,35,36,52],
 30:[31],31:[33,35],32:[31,35],33:[34,36,52],34:[52],35:[33,34],
 36:[39,52],37:[38],41:[40,49],42:[41],43:[23,42],
 44:[23,46,47,49],45:[44],46:[49],47:[49,55,56,57,58],48:[47,55,56],
 49:[58,69,70],50:[52],51:[50,52],53:[52],54:[39,64],57:[58],
 59:[61,63],60:[55,59],62:[63],63:[70,73,74],64:[67],65:[64,66],
 68:[69],69:[71],70:[69],74:[70,73],75:[73]}

def cubics(points, closed):
    n=len(points)
    for i in range(n if closed else n-1):
        p0=points[(i-1)%n] if i or closed else points[0]
        p1=points[i];p2=points[(i+1)%n]
        p3=points[(i+2)%n] if closed or i+2<n else points[-1]
        a=[p1[k]+(p2[k]-p0[k])*.11 for k in (0,1)]
        b=[p2[k]-(p3[k]-p1[k])*.11 for k in (0,1)]
        yield [p1,a,b,p2]

def evaluate(c,t):
    u=1-t
    return [u*u*u*c[0][k]+3*u*u*t*c[1][k]+3*u*t*t*c[2][k]+t*t*t*c[3][k] for k in (0,1)]

def split(c,t):
    lerp=lambda a,b:[a[k]+(b[k]-a[k])*t for k in (0,1)]
    a,b,d=lerp(c[0],c[1]),lerp(c[1],c[2]),lerp(c[2],c[3])
    e,f=lerp(a,b),lerp(b,d);g=lerp(e,f)
    return [c[0],a,e,g],[g,f,d,c[3]]

def subsection(c,a,b):
    left=split(c,b)[0] if b<1 else c
    return split(left,a/b)[1] if a>0 else left

def inside(p,poly):
    x,y=p;result=False;j=len(poly)-1
    for i in range(len(poly)):
        xi,yi=poly[i];xj,yj=poly[j]
        if (yi>y)!=(yj>y) and x<(xj-xi)*(y-yi)/(yj-yi)+xi:result=not result
        j=i
    return result

def visible_curves(number):
    c=contours[number-1]
    masks=[]
    for other in occlusion.get(number,[]):
        oc=contours[other-1]
        masks.append([evaluate(b,j/8) for b in cubics(oc['points'],True) for j in range(8)])
    pieces=[];current=[];cut=False
    for curve in cubics(c['points'],c['closed']):
        steps=24
        vis=[not any(inside(evaluate(curve,(j+.5)/steps),mask) for mask in masks) for j in range(steps)]
        start=0
        for j in range(1,steps+1):
            if j==steps or vis[j]!=vis[start]:
                if vis[start]:current.append(subsection(curve,start/steps,j/steps))
                else:
                    cut=True
                    if current:pieces.append(current);current=[]
                start=j
    if current:pieces.append(current)
    return pieces,c['closed'] and not cut

def curves_data(pieces,closed,ox=0,oy=0):
    commands=[]
    for piece in pieces:
        commands.append(f'M {piece[0][0][0]-ox:.2f} {piece[0][0][1]-oy:.2f}')
        for curve in piece:
            commands.append('C '+' '.join(f'{v-o:.2f}' for p in curve[1:] for v,o in zip(p,[ox,oy])))
        if closed:commands.append('Z')
    return ' '.join(commands)

def path_data(points, closed):
    # Gentle cubic interpolation preserves the many individually placed bends.
    n=len(points); result=[f'M {points[0][0]:.2f} {points[0][1]:.2f}']
    for i in range(n if closed else n-1):
        p0=points[(i-1)%n] if i or closed else points[0]
        p1=points[i]; p2=points[(i+1)%n]
        p3=points[(i+2)%n] if closed or i+2<n else points[-1]
        a=[p1[k]+(p2[k]-p0[k])*.11 for k in (0,1)]
        b=[p2[k]-(p3[k]-p1[k])*.11 for k in (0,1)]
        result.append('C '+' '.join(f'{v:.2f}' for v in a+b+p2))
    if closed: result.append('Z')
    return ' '.join(result)

def save():
    output=[]
    for i,c in enumerate(contours,1):
        x=min(p[0] for p in c['points']);y=min(p[1] for p in c['points'])
        local=[[p[0]-x,p[1]-y] for p in c['points']]
        pieces,visibleClosed=visible_curves(i)
        output.append({**c,'number':i,'x':x,'y':y,'visibleClosed':visibleClosed,'pieces':pieces,'data':curves_data(pieces,visibleClosed,x,y),'globalData':curves_data(pieces,visibleClosed)})
    (ROOT/'contours.json').write_text(json.dumps(output,indent=2),encoding='utf-8')
    colors=['#60FFC6','#FF8ADB','#FFE575','#7EDCFF']
    svg=['<svg xmlns="http://www.w3.org/2000/svg" width="1536" height="1024" viewBox="0 0 1536 1024">']
    for c in output:
        svg.append(f'<path id="pillar-{c["number"]:02}" d="{c["globalData"]}" fill="none" stroke="{colors[(c["number"]-1)%4]}" stroke-width="1.25" stroke-linecap="round" stroke-linejoin="round"><title>{c["name"]}</title></path>')
    svg.append('</svg>')
    (ROOT/'pillar-contours.svg').write_text('\n'.join(svg),encoding='utf-8')
    print(f'{len(output)} paths, {sum(len(c["points"]) for c in output)} hand-placed anchors')

if __name__=='__main__': save()
